<script setup lang="ts">
import { computed, ref } from 'vue'
import type { Dataset, Weekday } from '../lib/timetable'
import { roomUsage } from '../lib/insights'
import SortHeader from './SortHeader.vue'
import { sortRows } from '../lib/tableSort'
import { useTableSort } from '../lib/useTableSort'
const sorting = useTableSort('usage','desc')
const props = defineProps<{data:Dataset}>()
const day = ref('all'), start = ref(props.data.schedule_coverage?.start ?? '08:00'), end = ref(props.data.schedule_coverage?.end ?? '20:00'), kind = ref('all')
const state = computed(() => { try { return {rows:roomUsage(props.data,day.value === 'all' ? props.data.schedule_coverage?.weekdays ?? [] : [day.value as Weekday],start.value,end.value,kind.value),error:''} } catch(error) { return {rows:[],error:(error as Error).message} } })
const hours = computed(() => (state.value.rows.reduce((s,r) => s+r.occupied,0)/60).toFixed(1))
const percent = computed(() => { const total = state.value.rows.reduce((s,r)=>s+r.totalMinutes,0); return total ? (state.value.rows.reduce((s,r)=>s+r.occupied,0)/total*100).toFixed(1) : '0' })
const sortedRows = computed(() => sortRows(state.value.rows,row=>sorting.key.value==='hours'?row.occupied:sorting.key.value==='usage'?row.percent:row.room,sorting.direction.value,row=>row.room))
</script>
<template><section class="feature-page usage-page"><h1>Room usage</h1><div class="feature-controls usage-controls"><label>Days<select v-model="day"><option value="all">All published days</option><option v-for="d in data.schedule_coverage?.weekdays" :key="d">{{ d }}</option></select></label><label>From<input type="time" v-model="start" /></label><label>Until<input type="time" v-model="end" /></label><label>Room type<select v-model="kind"><option value="all">All types</option><option value="computer_lab">Computer labs</option><option value="classroom">Classrooms</option><option value="other">Other rooms</option></select></label></div><p v-if="state.error" class="source-banner" role="alert">{{ state.error }}</p><template v-else><div class="insight-metrics"><div><strong>{{ state.rows.length }}</strong>rooms monitored</div><div><strong>{{ hours }}</strong>scheduled room hours</div><div class="usage-percentage-card"><div class="usage-ring" role="img" :aria-label="`${percent}% scheduled usage`"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="usage-ring-track" cx="50" cy="50" r="42" /><circle class="usage-ring-fill" cx="50" cy="50" r="42" pathLength="100" :stroke-dasharray="`${percent} 100`" /></svg><strong>{{ percent }}<small>%</small></strong></div><div class="usage-ring-caption"><span>Scheduled usage</span><small>of the selected room hours</small></div></div></div><p class="availability-scope">Occupied minutes ÷ published minutes in the selected window. Overlapping bookings count once per room; every listed room in a shared block counts. Inventory-only rooms are excluded. This does not measure attendance or seat occupancy.</p><div class="usage-table-wrap"><table class="usage-table"><thead><tr><SortHeader label="Room" column="room" :sort-key="sorting.key.value" :direction="sorting.direction.value" @sort="sorting.toggle" /><SortHeader label="Scheduled hours" column="hours" :sort-key="sorting.key.value" :direction="sorting.direction.value" @sort="sorting.toggle" /><SortHeader label="Usage" column="usage" :sort-key="sorting.key.value" :direction="sorting.direction.value" @sort="sorting.toggle" /><th>By day</th></tr></thead><tbody><tr v-for="row in sortedRows" :key="row.room"><th>{{ row.room }}</th><td>{{ (row.occupied/60).toFixed(1) }}</td><td><span class="usage-value">{{ row.percent.toFixed(1) }}%</span><div class="usage-progress" role="meter" :aria-label="`${row.room} scheduled usage`" :aria-valuenow="Number(row.percent.toFixed(1))" :aria-valuemin="0" :aria-valuemax="100"><span :style="{width:`${row.percent}%`}" /></div></td><td><div class="daily-columns" :aria-label="`${row.room} daily scheduled hours`"><div v-for="d in row.byDay" :key="d.day" class="daily-column" :title="`${d.day}: ${(d.occupied/60).toFixed(1)} hours · ${(d.occupied/(row.totalMinutes/row.byDay.length)*100).toFixed(1)}%`"><span class="sr-only">{{ d.day }}: {{ (d.occupied/60).toFixed(1) }} scheduled hours.</span><div class="daily-column-track" aria-hidden="true"><span :style="{height:`${d.occupied/(row.totalMinutes/row.byDay.length)*100}%`}" /></div><small aria-hidden="true">{{ d.day.slice(0,3) }}</small></div></div></td></tr></tbody></table></div><p v-if="!state.rows.length">No timetable rooms match this type.</p></template></section></template>
